public async Task ExcludeFromCodeCoverageCanBeDisabledOnResolverAttribute()
{
    string source = TestSource.Replace("[GeneratedMessagePackResolver]", "[GeneratedMessagePackResolver(ExcludeFromCodeCoverage = false)]");
    IReadOnlyList<(string Path, string Text)> generated = await RunGeneratorAsync(source);

    string paths = string.Join(Environment.NewLine, generated.Select(g => g.Path));
    Assert.True(generated.Count >= 5, $"Expected generated formatters and resolver, got:{Environment.NewLine}{paths}");

    foreach ((string path, string text) in generated)
    {
        Assert.False(
            text.Contains(ExcludeAttribute),
            $"Generated file '{path}' should not contain {ExcludeAttribute} when the option is disabled.");
    }
}

